package com.rgapro1.ocaso;

import android.Manifest;
import android.app.Activity;
import android.app.AlertDialog;
import android.content.Intent;
import android.content.SharedPreferences;
import android.content.pm.PackageManager;
import android.graphics.Bitmap;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.hardware.biometrics.BiometricPrompt;
import android.os.Build;
import android.os.Bundle;
import android.os.CancellationSignal;
import android.text.InputType;
import android.view.Gravity;
import android.view.View;
import android.widget.*;
import com.google.mlkit.vision.common.InputImage;
import com.google.mlkit.vision.text.TextRecognition;
import com.google.mlkit.vision.text.TextRecognizer;
import com.google.mlkit.vision.text.latin.TextRecognizerOptions;
import org.json.JSONArray;
import org.json.JSONObject;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.concurrent.Executor;
import java.util.concurrent.Executors;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.PBEKeySpec;

public class MainActivity extends Activity {
    private static final int NAVY=Color.rgb(25,57,100), BLUE=Color.rgb(38,128,221), BG=Color.rgb(248,250,253), TEXT=Color.rgb(31,42,56), MUTED=Color.rgb(104,116,132), LINE=Color.rgb(226,231,238);
    private static final int ITER=120000, CAMERA_REQ=7001, CAMERA_RESULT=7002;
    private SharedPreferences prefs; private String currentUser; private LinearLayout content;
    private final Executor biometricExecutor=Executors.newSingleThreadExecutor(); private CancellationSignal biometricCancellation;
    private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    private LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private TextView tv(String s,float size,int color,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);v.setTypeface(bold?Typeface.DEFAULT_BOLD:Typeface.DEFAULT);v.setGravity(Gravity.CENTER_VERTICAL);return v;}
    private EditText edit(String hint){EditText e=new EditText(this);e.setHint(hint);e.setSingleLine(true);e.setTextSize(16);e.setPadding(dp(14),0,dp(14),0);return e;}
    private EditText pin(String hint){EditText e=edit(hint);e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);return e;}
    private GradientDrawable bg(int color,float radius){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp((int)radius));g.setStroke(dp(1),LINE);return g;}
    private Button action(String label,boolean primary){Button b=new Button(this);b.setText(label);b.setTextSize(15);b.setAllCaps(false);b.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);b.setPadding(dp(18),0,dp(14),0);b.setTextColor(primary?Color.WHITE:TEXT);b.setBackground(bg(primary?BLUE:Color.WHITE,18));return b;}
    private void base(){getWindow().setStatusBarColor(NAVY);getWindow().getDecorView().setSystemUiVisibility(0);}
    @Override public void onCreate(Bundle state){super.onCreate(state);base();try{prefs=getSharedPreferences("rgapro_local",MODE_PRIVATE);migrate();if(hasPin())showLogin();else createUser();}catch(Exception e){safeError();}}
    private void safeError(){LinearLayout l=col();l.setGravity(Gravity.CENTER);l.setPadding(dp(28),dp(28),dp(28),dp(28));l.addView(tv("RgaPro",34,NAVY,true));l.addView(tv("No se pudo iniciar. Tus datos locales siguen guardados.",16,TEXT,false));Button b=action("Reintentar",true);b.setGravity(Gravity.CENTER);b.setOnClickListener(v->onCreate(null));l.addView(b,new LinearLayout.LayoutParams(-1,dp(54)));setContentView(l);}
    private boolean hasPin(){return prefs.contains("pin_hash")&&prefs.contains("pin_salt");}
    private JSONObject users(){try{return new JSONObject(prefs.getString("users_json","{}"));}catch(Exception e){return new JSONObject();}}
    private void saveUsers(JSONObject u){prefs.edit().putString("users_json",u.toString()).apply();}
    private void migrate(){try{JSONObject u=users();if(u.length()==0&&hasPin()){JSONObject a=new JSONObject();a.put("pin_hash",prefs.getString("pin_hash",""));a.put("pin_salt",prefs.getString("pin_salt",""));a.put("policies",new JSONArray());u.put("Administrador",a);saveUsers(u);}}catch(Exception ignored){}}
    private byte[] derive(String p,byte[] salt)throws Exception{PBEKeySpec spec=new PBEKeySpec(p.toCharArray(),salt,ITER,256);try{return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();}finally{spec.clearPassword();}}
    private boolean verify(String user,String p){try{JSONObject o=users().optJSONObject(user);if(o==null)return false;byte[] h=android.util.Base64.decode(o.optString("pin_hash"),android.util.Base64.DEFAULT);byte[] s=android.util.Base64.decode(o.optString("pin_salt"),android.util.Base64.DEFAULT);return MessageDigest.isEqual(h,derive(p,s));}catch(Exception e){return false;}}
    private void logo(LinearLayout l){LinearLayout head=col();head.setGravity(Gravity.CENTER);head.setPadding(0,dp(24),0,dp(18));TextView mark=tv("◈",34,BLUE,true);mark.setGravity(Gravity.CENTER);head.addView(mark,new LinearLayout.LayoutParams(-1,dp(34)));TextView name=tv("RgaPro",30,NAVY,true);name.setGravity(Gravity.CENTER);head.addView(name);l.addView(head);}
    private void createUser(){LinearLayout l=col();l.setBackgroundColor(BG);l.setPadding(dp(24),dp(14),dp(24),dp(24));logo(l);TextView title=tv("Tu cartera profesional",24,TEXT,true);title.setGravity(Gravity.CENTER);l.addView(title);TextView sub=tv("Simple, segura y bajo tu control.",16,MUTED,false);sub.setGravity(Gravity.CENTER);l.addView(sub);Space sp=new Space(this);l.addView(sp,new LinearLayout.LayoutParams(1,dp(20)));EditText n=edit("Nombre de usuario"),p=pin("Clave de 6 dígitos"),p2=pin("Repite la clave");l.addView(n,new LinearLayout.LayoutParams(-1,dp(52)));l.addView(p,new LinearLayout.LayoutParams(-1,dp(52)));l.addView(p2,new LinearLayout.LayoutParams(-1,dp(52)));Button b=action("Crear mi cartera",true);b.setGravity(Gravity.CENTER);b.setOnClickListener(v->{String name=n.getText().toString().trim(),a=p.getText().toString(),c=p2.getText().toString();if(name.isEmpty()||!a.matches("\\d{6}")||!a.equals(c)){Toast.makeText(this,"Introduce un nombre y una clave de 6 dígitos",Toast.LENGTH_LONG).show();return;}try{byte[] salt=new byte[16];new SecureRandom().nextBytes(salt);JSONObject o=new JSONObject();o.put("pin_hash",android.util.Base64.encodeToString(derive(a,salt),android.util.Base64.NO_WRAP));o.put("pin_salt",android.util.Base64.encodeToString(salt,android.util.Base64.NO_WRAP));o.put("policies",new JSONArray());JSONObject u=users();u.put(name,o);saveUsers(u);prefs.edit().putString("pin_hash",o.getString("pin_hash")).putString("pin_salt",o.getString("pin_salt")).apply();currentUser=name;home();}catch(Exception e){Toast.makeText(this,"No se pudo crear la cartera",Toast.LENGTH_LONG).show();}});l.addView(b,new LinearLayout.LayoutParams(-1,dp(54)));setContentView(l);}
    private void showLogin(){LinearLayout l=col();l.setBackgroundColor(BG);l.setPadding(dp(24),dp(14),dp(24),dp(24));logo(l);TextView welcome=tv("Bienvenido de nuevo",24,TEXT,true);welcome.setGravity(Gravity.CENTER);l.addView(welcome);TextView sub=tv("Acceso seguro a tu cartera",16,MUTED,false);sub.setGravity(Gravity.CENTER);l.addView(sub);Space sp=new Space(this);l.addView(sp,new LinearLayout.LayoutParams(1,dp(22)));Spinner s=new Spinner(this);ArrayList<String> names=new ArrayList<>();Iterator<String> it=users().keys();while(it.hasNext())names.add(it.next());Collections.sort(names);if(names.isEmpty()){createUser();return;}s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));l.addView(s,new LinearLayout.LayoutParams(-1,dp(52)));Space sp2=new Space(this);l.addView(sp2,new LinearLayout.LayoutParams(1,dp(12)));Button b=action("🔐  Entrar con clave",true);b.setGravity(Gravity.CENTER);b.setOnClickListener(v->login(String.valueOf(s.getSelectedItem())));l.addView(b,new LinearLayout.LayoutParams(-1,dp(54)));Button bio=action("●  Entrar con huella / biometría",false);bio.setGravity(Gravity.CENTER);bio.setOnClickListener(v->biometricLogin(String.valueOf(s.getSelectedItem())));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,dp(54));bp.topMargin=dp(10);l.addView(bio,bp);TextView foot=tv("Tu información permanece en tu dispositivo.",13,MUTED,false);foot.setGravity(Gravity.CENTER);LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(-1,dp(44));fp.topMargin=dp(18);l.addView(foot,fp);setContentView(l);}
    private void login(String user){EditText e=pin("Clave de 6 dígitos");AlertDialog d=new AlertDialog.Builder(this).setTitle("Desbloquear · "+user).setView(e).setNegativeButton("Cancelar",null).setPositiveButton("Entrar",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{if(verify(user,e.getText().toString())){currentUser=user;d.dismiss();home();}else e.setError("Clave incorrecta");}));d.show();}
    private void biometricLogin(String user){if(Build.VERSION.SDK_INT<28){Toast.makeText(this,"La biometría requiere Android 9 o superior",Toast.LENGTH_LONG).show();return;}BiometricPrompt.AuthenticationCallback cb=new BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult r){runOnUiThread(()->{currentUser=user;home();});}@Override public void onAuthenticationError(int e,CharSequence m){runOnUiThread(()->Toast.makeText(MainActivity.this,"Biometría: "+m,Toast.LENGTH_SHORT).show());}};BiometricPrompt prompt=new BiometricPrompt.Builder(this).setTitle("RgaPro").setSubtitle("Acceso seguro").setDescription("Confirma tu identidad con la biometría del dispositivo").setNegativeButton("Usar clave",command->runOnUiThread(command),d->{}).build();biometricCancellation=new CancellationSignal();prompt.authenticate(biometricCancellation,biometricExecutor,cb);}
    private JSONArray policies(){try{JSONObject o=users().optJSONObject(currentUser);JSONArray a=o==null?null:o.optJSONArray("policies");return a==null?new JSONArray():a;}catch(Exception e){return new JSONArray();}}
    private TextView section(String title,String sub){TextView t=tv(title+"\n"+sub,18,TEXT,true);t.setPadding(dp(18),dp(14),dp(18),dp(14));return t;}
    private void home(){LinearLayout root=col();root.setBackgroundColor(BG);LinearLayout top=col();top.setBackgroundColor(NAVY);top.setPadding(dp(20),dp(12),dp(20),dp(16));TextView brand=tv("RgaPro",28,Color.WHITE,true);brand.setGravity(Gravity.CENTER);top.addView(brand);TextView hi=tv("Hola, "+currentUser+" 👋",18,Color.WHITE,false);hi.setPadding(0,dp(6),0,0);top.addView(hi);root.addView(top);ScrollView sc=new ScrollView(this);LinearLayout body=col();body.setPadding(dp(18),dp(18),dp(18),dp(24));body.addView(section("¿Qué quieres hacer hoy?","Todo en un solo lugar"));addMenu(body,"👤","Tus clientes","Buscar por nombre, DNI, teléfono o póliza",v->clients());addMenu(body,"▣","Tus pólizas","Separadas por tipo de seguro",v->policiesPage());addMenu(body,"▤","Documentos","Escanear y leer datos automáticamente",v->scanDocument());addMenu(body,"♧","Vencimientos","Alertas a 60 · 45 · 30 · 15 días",v->expiries());addMenu(body,"🔒","Seguridad y privacidad","Usuarios, biometría y compartir",v->security());TextView note=tv("RgaPro · Gestión profesional",13,MUTED,false);note.setGravity(Gravity.CENTER);LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(-1,dp(45));np.topMargin=dp(12);body.addView(note,np);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));Button out=action("Cerrar sesión",false);out.setGravity(Gravity.CENTER);LinearLayout.LayoutParams op=new LinearLayout.LayoutParams(-1,dp(50));op.setMargins(dp(18),0,dp(18),dp(14));root.addView(out,op);out.setOnClickListener(v->{currentUser=null;showLogin();});setContentView(root);}
    private void addMenu(LinearLayout body,String icon,String title,String sub,View.OnClickListener click){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.HORIZONTAL);card.setGravity(Gravity.CENTER_VERTICAL);card.setPadding(dp(16),dp(10),dp(12),dp(10));card.setBackground(bg(Color.WHITE,18));TextView i=tv(icon,28,BLUE,true);i.setGravity(Gravity.CENTER);card.addView(i,new LinearLayout.LayoutParams(dp(48),dp(64)));LinearLayout words=col();words.setPadding(dp(8),0,0,0);words.addView(tv(title,18,TEXT,true));words.addView(tv(sub,13,MUTED,false));card.addView(words,new LinearLayout.LayoutParams(0,dp(64),1));TextView arrow=tv("›",30,MUTED,false);arrow.setGravity(Gravity.CENTER);card.addView(arrow,new LinearLayout.LayoutParams(dp(28),dp(64)));card.setOnClickListener(click);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,dp(86));cp.bottomMargin=dp(10);body.addView(card,cp);}
    private void page(String title,String subtitle){LinearLayout root=col();root.setBackgroundColor(BG);LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);head.setPadding(dp(12),dp(10),dp(18),dp(10));head.setBackgroundColor(NAVY);Button back=action("‹",false);back.setTextColor(Color.WHITE);back.setBackgroundColor(Color.TRANSPARENT);back.setGravity(Gravity.CENTER);back.setOnClickListener(v->home());head.addView(back,new LinearLayout.LayoutParams(dp(48),dp(48)));LinearLayout htxt=col();htxt.addView(tv(title,20,Color.WHITE,true));htxt.addView(tv(subtitle,12,Color.WHITE,false));head.addView(htxt);root.addView(head);content=col();content.setPadding(dp(16),dp(16),dp(16),dp(20));ScrollView sc=new ScrollView(this);sc.addView(content);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);}
    private void clients(){page("Tus clientes","Busca por cualquier dato");EditText q=edit("Nombre, DNI, teléfono, póliza...");q.setBackground(bg(Color.WHITE,16));content.addView(q,new LinearLayout.LayoutParams(-1,dp(54)));LinearLayout list=col();LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(12);content.addView(list,lp);Runnable render=()->{list.removeAllViews();JSONArray a=policies();for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p!=null&&matches(p,q.getText().toString())){Button b=action("👤  "+p.optString("holder","Sin titular")+"\n      "+p.optString("type","Otros")+" · "+p.optString("number",""),false);b.setOnClickListener(v->detail(p));list.addView(b,new LinearLayout.LayoutParams(-1,dp(72)));}}};q.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){render.run();}public void afterTextChanged(android.text.Editable e){}});render.run();}
    private boolean matches(JSONObject p,String q){if(q==null||q.trim().isEmpty())return true;String n=q.toLowerCase(Locale.ROOT);for(String k:new String[]{"holder","holderDni","phone","email","address","type","number","expiry","ocrText","members"})if(p.optString(k).toLowerCase(Locale.ROOT).contains(n))return true;return false;}
    private void detail(JSONObject p){StringBuilder msg=new StringBuilder();msg.append("Titular: ").append(p.optString("holder","—"));msg.append("\nDNI: ").append(p.optString("holderDni","—"));msg.append("\nTeléfono: ").append(p.optString("phone","—"));msg.append("\nEmail: ").append(p.optString("email","—"));msg.append("\nTipo: ").append(p.optString("type","—"));msg.append("\nPóliza: ").append(p.optString("number","—"));msg.append("\nVencimiento: ").append(p.optString("expiry","—"));JSONArray members=p.optJSONArray("members");if(members!=null&&members.length()>0){msg.append("\n\nPersonas incluidas:");for(int i=0;i<members.length();i++)msg.append("\n• ").append(members.optString(i));}new AlertDialog.Builder(this).setTitle("Ficha del cliente").setMessage(msg.toString()).setPositiveButton("Cerrar",null).setNeutralButton("Compartir",(d,w)->share(msg.toString())).show();}
    private void share(String msg){Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,msg);startActivity(Intent.createChooser(i,"Compartir datos"));}
    private void policiesPage(){page("Tus pólizas","Elige el tipo de seguro");for(String type:new String[]{"Todas","Decesos","Vida","Hogar","Auto","Salud","Accidentes","Otros"}){Button b=action("▸  "+type,false);b.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);b.setOnClickListener(v->filter(type));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,dp(58));bp.bottomMargin=dp(8);content.addView(b,bp);}}
    private void filter(String type){page(type,"Pólizas de este tipo");JSONArray a=policies();int count=0;for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p!=null&&(type.equals("Todas")||type.equals(p.optString("type")))){count++;Button b=action("👤  "+p.optString("holder","Sin titular")+"\n      "+p.optString("number","")+"  ·  "+p.optString("expiry",""),false);b.setOnClickListener(v->detail(p));content.addView(b,new LinearLayout.LayoutParams(-1,dp(72)));}}if(count==0)content.addView(tv("No hay pólizas registradas en esta categoría.",15,MUTED,false));}
    private void expiries(){page("Vencimientos","Control visual de tus próximas renovaciones");JSONArray a=policies();for(int days:new int[]{60,45,30,15}){TextView h=tv("⏰  "+days+" días",18,TEXT,true);h.setPadding(dp(6),dp(12),dp(6),dp(8));content.addView(h);int n=0;for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p!=null&&daysToExpiry(p.optString("expiry"))==days){n++;content.addView(action("👤  "+p.optString("holder","Sin titular")+" · "+p.optString("type","Otros"),false),new LinearLayout.LayoutParams(-1,dp(62)));}}if(n==0)content.addView(tv("Sin pólizas en este plazo.",13,MUTED,false));}}
    private int daysToExpiry(String value){try{Date d=new SimpleDateFormat("yyyy-MM-dd",Locale.US).parse(value);return (int)Math.round((d.getTime()-System.currentTimeMillis())/86400000.0);}catch(Exception e){return -1;}}
    private void security(){page("Seguridad","Tu información, bajo tu control");content.addView(tv("🔐 Acceso protegido",20,TEXT,true));content.addView(tv("Clave de 6 dígitos y biometría del dispositivo cuando esté disponible.",15,MUTED,false));content.addView(tv("👥 Usuarios separados",20,TEXT,true));content.addView(tv("Cada usuario trabaja con su propia cartera y sus propios datos.",15,MUTED,false));content.addView(tv("↗ Compartir solo cuando tú lo decidas",20,TEXT,true));content.addView(tv("RgaPro no comparte datos automáticamente. La acción Compartir siempre la inicia el usuario.",15,MUTED,false));}
    private void scanDocument(){if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.CAMERA},CAMERA_REQ);return;}launchCamera();}
    private void launchCamera(){try{Intent i=new Intent(android.provider.MediaStore.ACTION_IMAGE_CAPTURE);if(i.resolveActivity(getPackageManager())!=null)startActivityForResult(i,CAMERA_RESULT);else Toast.makeText(this,"No hay cámara disponible",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,"No se pudo abrir la cámara",Toast.LENGTH_LONG).show();}}
    @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==CAMERA_REQ&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)launchCamera();else if(r==CAMERA_REQ)Toast.makeText(this,"Necesito permiso de cámara para escanear documentos",Toast.LENGTH_LONG).show();}
    @Override protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r==CAMERA_RESULT&&result==RESULT_OK&&data!=null&&data.getExtras()!=null){Object o=data.getExtras().get("data");if(o instanceof Bitmap)runOcr((Bitmap)o);else Toast.makeText(this,"No se obtuvo la imagen",Toast.LENGTH_LONG).show();}}
    private void runOcr(Bitmap bitmap){Toast.makeText(this,"Leyendo documento…",Toast.LENGTH_SHORT).show();InputImage image=InputImage.fromBitmap(bitmap,0);TextRecognizer recognizer=TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);recognizer.process(image).addOnSuccessListener(result->showOcrResult(result.getText())).addOnFailureListener(e->Toast.makeText(this,"No se pudo leer el documento",Toast.LENGTH_LONG).show()).addOnCompleteListener(t->recognizer.close());}
    private void showOcrResult(String raw){String clean=raw==null?"":raw.trim();String dni=extractDni(clean),phone=extractPhone(clean),email=extractEmail(clean);String summary="Datos detectados\n\nDNI/NIE: "+(dni.isEmpty()?"—":dni)+"\nTeléfono: "+(phone.isEmpty()?"—":phone)+"\nEmail: "+(email.isEmpty()?"—":email)+"\n\nTexto leído:\n"+clean;new AlertDialog.Builder(this).setTitle("📄 Documento leído").setMessage(summary).setNegativeButton("Cerrar",null).setPositiveButton("Buscar cliente",(d,w)->clients()).show();}
    private String extractDni(String s){java.util.regex.Matcher m=java.util.regex.Pattern.compile("\\b[XYZ]?\\d{7,8}[A-Z]\\b",java.util.regex.Pattern.CASE_INSENSITIVE).matcher(s.replace(" ",""));return m.find()?m.group().toUpperCase(Locale.ROOT):"";}
    private String extractPhone(String s){java.util.regex.Matcher m=java.util.regex.Pattern.compile("\\b(?:\\+34\\s?)?[6789]\\d{8}\\b").matcher(s.replace("-"," "));return m.find()?m.group():"";}
    private String extractEmail(String s){java.util.regex.Matcher m=java.util.regex.Pattern.compile("[A-Z0-9._%+-]+@[A-Z0-9.-]+\\.[A-Z]{2,}",java.util.regex.Pattern.CASE_INSENSITIVE).matcher(s);return m.find()?m.group():"";}
    @Override protected void onDestroy(){if(biometricCancellation!=null)biometricCancellation.cancel();super.onDestroy();}
}
